  const faceContour = jaw > .5
    ? `M ${244 - faceWidth} 268 C 257 198 307 166 365 168 C 411 168 446 207 452 275 C 458 351 432 421 390 472 C 376 490 362 511 350 514 C 332 512 315 498 300 482 C 263 441 241 382 239 315 C 238 294 240 279 244 268 Z`
    : `M ${246 - faceWidth} 266 C 258 196 309 165 366 168 C 407 171 435 207 441 276 C 447 347 428 416 391 466 C 376 491 362 511 350 507 C 332 502 312 484 294 464 C 258 424 239 369 240 313 C 240 293 242 278 246 266 Z`;
  const hairFrontStudio = jaw > .5
