  const bw = IYH_J.bw, bh = IYH_J.bh             // J60 brick footprint (viewBox units)
  // coverage was baked at 720x760; scale brick footprints to the actual viewBox
  const sx = vw / 720, sy = vh / 760
  const cov = IYH_FACE_COV_BYTES                 // decoded once at module load (pure-JS, no atob)
  const t = Number(clock) || 0
  const seed = iiyhJSeed(Math.max(0, Math.floor(t / 0.9)))       // shimmer re-roll per poll
  const effFloor = Math.min(1, IYH_J.floor + IYH_J.lift)
