// Build one surface's atlas: a hidden <svg> of <symbol> defs. The tintable
// contract lives on the symbol: stroke/fill = currentColor, so every use
// site picks its color with plain CSS (theme vars). Emits BOTH sets: the
// 14x14 creature/chrome atlas and the 16x16 owner-approved spec atlas
// (pencil family at 1.25/round, everything else 1.5/miter).
function iyhAtlasSvg(prefix) {
  const spec = Object.keys(IYH_SPEC_ICONS).map((n) => {
    const pencil = IYH_SPEC_PENCIL[n]
    return '<symbol id="' + prefix + '-' + n + '" viewBox="0 0 16 16" fill="none" ' +
      'stroke="currentColor" stroke-width="' + (pencil ? '1.25' : '1.5') + '" ' +
      'stroke-linecap="round" stroke-linejoin="' + (pencil ? 'round' : 'miter') + '">' +
      IYH_SPEC_ICONS[n].map((d) => '<path d="' + d + '"/>').join('') +
      '</symbol>'
  }).join('')
  return '<svg xmlns="http://www.w3.org/2000/svg" style="display:none" aria-hidden="true">' +
    Object.keys(IYH_ICON_DEFS).map((n) =>
      '<symbol id="' + prefix + '-' + n + '" viewBox="0 0 14 14" fill="none" ' +
      'stroke="currentColor" stroke-width="1.25" stroke-linecap="round" ' +
      'stroke-linejoin="round">' + IYH_ICON_DEFS[n] + '</symbol>'
    ).join('') +
    spec +
    '</svg>'
}

function IyhAtlas({ prefix }) {
  return jsx('div', {
    'aria-hidden': true,
    style: { display: 'none' },
    dangerouslySetInnerHTML: { __html: iyhAtlasSvg(prefix) },
  })
}

// One tintable use: <svg><use href="#prefix-name"/></svg>. `color` takes
// any CSS color — theme vars included; that is the tinting seam.
function IyhIcon({ prefix, name, size = 14, color, style, vb = '0 0 14 14' }) {
  return jsx('svg', {
    width: size,
    height: size,
    viewBox: vb,
    style: {
      color: color || 'var(--ui-text-secondary)',
      flexShrink: 0,
      display: 'block',
      ...style,
    },
    'aria-hidden': true,
    children: jsx('use', { href: '#' + prefix + '-' + name }),
  })
}

// Pet tint: operational states ride the instrument tokens — friction on the
// destructive token, success on the accent phosphor, everything else muted.
function petIconColor(state) {
  if (state === 'friction') return 'var(--dt-destructive, var(--ui-accent))'
  if (state === 'successful') return 'var(--ui-accent)'
  return 'var(--ui-text-secondary)'
}
// IYH-ICONS-END

function fmtTokens(n) {
  if (n === null || n === undefined) return '–'
  if (n >= 1e6) return (n / 1e6).toFixed(1).replace(/\.0$/, '') + 'M'
  if (n >= 1e3) return (n / 1e3).toFixed(1).replace(/\.0$/, '') + 'k'
  return String(n)
}

function fmtClock(ts) {
  if (!ts) return '–'
  const d = new Date(ts * 1000)
  const p = (x) => String(x).padStart(2, '0')
  return p(d.getHours()) + ':' + p(d.getMinutes())
}

// Backend-read diagnostic: surface the ACTUAL /metrics failure instead of
// collapsing every ctx.rest rejection into "backend offline". The rejection
// shape isn't contract-pinned (it may be an Error carrying .status /
// .statusCode, a string, or a plain object), so we extract an HTTP status from
// every plausible location and classify it — this immediately distinguishes
// auth failure (401/403), a route that was never mounted into the gateway
// (404), a backend fault (5xx), and a connectivity loss (no status at all).
function backendErrorLabel(err) {
  const src =
    err == null
      ? ''
      : String(
          err &&
          (err.message || err.detail || err.reason || err.status || err.statusCode) != null
            ? err.message || err.detail || err.reason || err.status || err.statusCode
            : err,
        )
  let code = null
  if (err && typeof err === 'object') {
    for (const k of ['status', 'statusCode', 'code']) {
      if (typeof err[k] === 'number' && err[k] >= 400 && err[k] < 600) {
        code = err[k]
        break
      }
    }
  }
  if (code === null) {
    const m = src.match(/\b([45]\d\d)\b/)
    if (m) code = Number(m[1])
  }
  let label
  if (code === 401) label = 'unauthorized (401)'
  else if (code === 403) label = 'forbidden (403)'
  else if (code === 404) label = 'route not mounted (404)'
  else if (code !== null && code >= 500) label = 'backend error (' + code + ')'
  else if (code !== null) label = 'HTTP ' + code
  else if (/ECONN|fetch failed|network|unreachable|timed? ?out|socket/i.test(src))
    label = 'unreachable (connection)'
  else if (src.trim()) label = 'read failed'
  else label = 'backend offline'
  return label
}

// PULSE-START
// Pure PULSE matrix helpers (no DOM/canvas): column mapping + cell values.
// Column mapping (F1): the visible order is LIVE / GOAL / GOOD / FRICTION
// per the original design (pulse/matrix.py). The server's `columns` list
// still carries the legacy 'unlabeled' entry, but no row carries an
// `unlabeled` cell — unlabeled tools report state='learning' on their
// goal/good/friction cells (row.state / row.labeled), so 'unlabeled'
// folds into those cells and is dropped from the visible columns.
// LIVE is derived client-side from the per-row `live` counts the response
// already carries (calls_started/calls_completed/errors) — no engine
// field is needed and none is invented here.
function pulseCellValue(cell) {
  if (!cell || typeof cell !== 'object') return null
  const v = cell.value
  return typeof v === 'number' && Number.isFinite(v)
    ? Math.min(1, Math.max(0, v))
    : null
}

function pulseColumns(pulse) {
  const semantic = ['goal', 'good', 'friction']
  const fromServer = pulse && Array.isArray(pulse.columns)
    ? pulse.columns.filter((c) => semantic.indexOf(c) !== -1)
    : []
  const rest = fromServer.length
    ? semantic.filter((c) => fromServer.indexOf(c) !== -1)
    : semantic
  return ['live', ...rest]
}

// LIVE value: squash unbounded activity counts onto 0..1 (1 call -> 0.5,
// saturating towards 1) so the cell shares the alpha encoding of the
// similarity cells. No recorded activity -> null (neutral/blank), which
// also marks the row as not live for the muted row styling below.
function pulseLiveValue(row) {
  const live = row && typeof row.live === 'object' ? row.live : null
  if (!live) return null
  const total = [live.calls_started, live.calls_completed, live.errors]
    .reduce((s, v) => s + (typeof v === 'number' && Number.isFinite(v) ? v : 0), 0)
  if (total <= 0) return null
  return 1 - 1 / (1 + total)
}
// Momentum (Tier-0 positive feedback): the per-tool surge value the server
// attaches to each row (0.5 = steady, >0.5 surging, <0.5 cooling). Read
// defensively so a legacy /pulse payload without momentum degrades to the
// neutral 0.5 instead of breaking the sort.
function pulseMomentumValue(row) {
  const m = row && row.momentum && typeof row.momentum.value === 'number'
    ? row.momentum.value : null
  return m === null ? 0.5 : m
}
// A one-glyph surge marker for the LIVE cell / row label: text-only, no
// color (the theme carries no dedicated token; the accent cell already
// glows). Surging / cooling get a glyph; steady or a legacy payload (no
// momentum) yields '' so idle rows stay visually quiet.
function pulseMomentumGlyph(row) {
  const s = row && row.momentum ? row.momentum.state : null
  if (s === 'surging') return '\u25B2'   // ▲ surging
  if (s === 'cooling') return '\u25BC'    // ▼ cooling
  return ''
}
// Row selection is deterministic and view-side only: the server returns
// rows in first_seen order; the pane shows the most relevant `cap` of them.
// Ranking: (1) momentum descending — a tool hotter than its long-run
// baseline (a surge) pops to the front, which is the point; (2) live
// activity total descending; (3) strongest semantic cell (goal/good/
// friction max 0..1) descending; (4) original server order (stable). No
// hardcoded tool list, no randomness.
function selectPulseRows(rows, cap) {
  if (!Array.isArray(rows) || cap <= 0) return []
  const ranked = rows.map((row, i) => {
    const live = pulseLiveValue(row)
    const liveT = live === null ? -1 : live
    let sem = 0
    ;['goal', 'good', 'friction'].forEach((c) => {
      const v = pulseCellValue(row ? row[c] : null)
      if (v !== null && v > sem) sem = v
    })
    return { row: row, i: i, liveT: liveT, sem: sem, mom: pulseMomentumValue(row) }
  })
  ranked.sort((a, b) => (b.mom - a.mom) || (b.liveT - a.liveT) || (b.sem - a.sem) || (a.i - b.i))
  return ranked.slice(0, cap).map((r) => r.row)
}
// Discrete 3-band encoding of a semantic cell from the server's cell.level:
// 'empty' (neutral / learning / no cell / no level), 'weak', 'strong'. This
// replaces the continuous alpha ramp on goal/good/friction so a weak fill no
// longer blurs into an empty one. Theme carries no dedicated token, so the
// band is expressed as a fixed opacity step on the accent/danger fill.
function pulseBand(cell) {
  const lvl = cell && typeof cell === 'object' ? cell.level : null
  if (lvl === 'strong') return 'strong'
  if (lvl === 'weak') return 'weak'
  return 'empty'
}
// Deterministic word-only verdict (confidence-gated, no digits, no clock):
// compact = the top-ranked row's single clause (the one token the 48px lane
// shows); full = up to 3 clauses for the expanded view. A weak/empty row
// yields no clause (honest absence, never filler). The template skeleton is
// digit-free; tool names are labels, not metrics.
function buildPulseVerdict(shownRows) {
  const cols = ['goal', 'good', 'friction']
  const clauseFor = (row) => {
    const tool = String((row && (row.tool_name || row.tool)) || '').trim()
    const st = row && row.momentum ? row.momentum.state : null
    if (st === 'surging') return tool ? tool + ' surging ahead of baseline' : ''
    if (st === 'cooling') return tool ? tool + ' cooling off baseline' : ''
    for (const c of cols) {
      if (pulseBand(row && row[c]) === 'strong') return tool ? tool + ' reads strong on ' + c : ''
    }
    return ''
  }
  const rows = Array.isArray(shownRows) ? shownRows : []
  const clauses = rows.slice(0, 3).map(clauseFor).filter((s) => s !== '')
  return { compact: clauseFor(rows[0]) || '', full: clauses.join('; ') }
}
// Recency read (move 4): PULSE is the NOW snapshot; this is the FRESHNESS
// of that snapshot — how old the row's `last_seen` is at render time. The
// multi-point history (trend) stays owned by DRIFT (its sparklines in the
// portrait tab), so PULSE gains NO sparkline / delta here, only this
// freshness read. Pure + deterministic: `nowSec` is supplied by the caller
// (the pane passes Date.now()/1000) — this helper never reads the clock.
// Honest absence: no usable last_seen -> never show a fabricated recency.
function pulseRecency(lastSeen, nowSec) {
  const s = Number(lastSeen)
  if (!Number.isFinite(s) || s <= 0) return { word: '', label: 'no activity yet' }
  const n = Number(nowSec)
  const age = Number.isFinite(n) ? Math.max(0, n - s) : 0
  if (age < 60) return { word: 'now', label: 'just now' }
  if (age < 3600) return { word: 'recent', label: Math.max(1, Math.round(age / 60)) + 'm ago' }
  if (age < 86400) return { word: 'today', label: Math.round(age / 3600) + 'h ago' }
  return { word: 'stale', label: Math.round(age / 86400) + 'd ago' }
}
// PULSE-END

// STAGE4-START
// =====================================================================
// Stage 4 — measured capacity + surface compositions + PULSE data seam.
// Pure helpers (no DOM / no host / no React): composition selection,
// visible-capacity calculation, focus/activation, and the injectable
// PULSE adapter. The desktop consumes the v2 contract below; Stage 3
// swaps the adapter source to the lanes API without touching the
// composition code because ALL lane-shape knowledge lives in
// adaptPulseToLanes.
//
// v2 contract (verbatim, owner-specified 2026-11-09):
//   type PulseState = "empty" | "learning" | "provisional" | "ready";
//   type PulseLevel = "neutral" | "weak" | "strong";
//   type PulseMomentumState = "surging" | "steady" | "cooling";
//   type PulseLaneOrder = ["live", "goal", "good", "friction"];
//   interface PulseSupport { count: number; required: number; ratio: number; }
//   interface PulseResponseV2 {
//     schema_version: 2; available: boolean;
//     lane_order: PulseLaneOrder;
//     lanes: { live: PulseLiveEntry[]; goal: PulseGoalEntry[]; good: PulseGoodEntry[]; friction: PulseFrictionEntry[]; };
//     rows: LegacyPulseRow[]; columns: ["goal","good","friction","unlabeled"];
//   }
//   interface PulseEntryBase { tool_id: number; tool_name: string; rank: number; }
//   interface PulseLiveEntry extends PulseEntryBase {
//     activity: { calls_started: number; calls_completed: number; errors: number; first_seen: number | null; last_seen: number | null; recent_capsules: number; };
//     momentum: { momentum: number; surge: number; value: number; state: PulseMomentumState; };
//   }
//   interface PulseGoalEntry extends PulseEntryBase {
//     value: number | null; threshold: number; level: PulseLevel; state: PulseState; support: PulseSupport;
//     evidence: { source: "prototype_banks" | "recent_capsules" | "none"; prototype_count: number; capsule_count: number; };
//   }
//   interface PulseGoodEntry extends PulseEntryBase {
//     value: number | null; threshold: number; level: PulseLevel; state: PulseState; support: PulseSupport;
//     evidence_source: "good_prototypes" | "none";
//   }
//   interface PulseFrictionPart { value: number | null; level: PulseLevel; state: PulseState; support: PulseSupport; }
//   interface PulseFrictionEntry extends PulseEntryBase {
//     value: number | null; threshold: number; level: PulseLevel; state: PulseState;
//     dominant_source: "user" | "objective" | null; user: PulseFrictionPart; objective: PulseFrictionPart;
//   }
//   interface LegacyPulseRow { [key: string]: unknown; }

// Composition: wide-shallow -> bottom, tall-narrow -> sidebar.
// Orientation comes from the MEASURED pane box (width AND height),
// never from width alone. A narrow but shallow surface stays bottom
// (plan section 8.1); a very short allocation always stays bottom and
